  const rows = text.match(/<tr[^>]*>[\s\S]*?<\/tr>/gi);
  if (rows) {
    rows.forEach(r => {
      const clean = r.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      if (clean.includes('법인') || clean.includes('사업자') || clean.includes('대표') || clean.includes('설립')) {
        console.log('Row:', clean);
      }
    });
  }
}
test();

